CoreAccountingUnits GlAccountingPeriodEvents::getCoreAccountingUnits(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from core_accounting_units where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *accountingUnitId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return CoreAccountingUnits(r[0]);
}

